head.script:
scwin.screenId = "jldstf05005";

///////// 1. 변수 및 선언 영역 /////////

scwin.panel_mkt_gubun = $c.util.getComponent('panel_mkt_gubun');

scwin.grd_List = $c.util.getComponent('grd_List');

scwin.panel_page = $c.util.getComponent('panel_page');

scwin.clickBzProcsNo = "";

scwin.vScrenID = "ULDSTF05005.gfm";


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        fn_initSearchDate(cal_edt_SDate, cal_edt_EDate);
        $c.fil.Combo_CBDataSetPeriod(slc_cmb_PeriodTp);
        if ($c.session.getUserInfo("market") === "1" || $c.session.getUserInfo("market") === "2" || $c.session.getUserInfo("market") === "6") {
            console.warn('[sdd] 미포팅 대입 — 아래 주석의 대상'); /* 미포팅 대입 대상: grd_List.getColumnInfo("TR_MKT_NM", "Show") */
            console.warn('[sdd] 미포팅 대입 — 아래 주석의 대상'); /* 미포팅 대입 대상: grd_List.getColumnInfo("FSS_UNQ_NO_DUP_YN", "Show") */
            $c.fil.setObjectValue(rd_rdo_SPOT_ISU_TRD_MKT_TP_CD, $c.session.getUserInfo("market"));
            $c.fil.showObj(scwin.panel_mkt_gubun, false);
        } else {
            $c.fil.showObj(scwin.panel_mkt_gubun, true);
        }
        if ($c.session.getUserInfo("market") === "6") {
            const usrCBData = "'ST^주권";
            if(slc_cmb_NEW_SECUGRP_ID)slc_cmb_NEW_SECUGRP_ID.CBData=usrCBData;
        }
        scwin.fn_list_sync();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf05005.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dts_List = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List')) : $c.util.getComponent('dts_List');

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf05005.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Search_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin btn_Search_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if ($c.fil.compareFromToDate2(cal_edt_SDate, cal_edt_EDate)) {
            scwin.fn_list_sync();
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf05005.btn_Search_onclick' }); }
};

/**
 * @method
 * @name scwin.dts_List_onloaderror
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.dts_List_onloaderror = function () {
    /* sdd-asis-lifecycle:begin dts_List_onloaderror — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.fil.alert_error(scwin.dts_List);
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.dts_List_onloadcompleted
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowcount
 * @returns
 * @hidden N
*/
scwin.dts_List_onloadcompleted = function (rowcount) {
    /* sdd-asis-lifecycle:begin dts_List_onloadcompleted — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.fil.FillGridHeaderTotalCnt(rowcount, scwin.panel_page);
    void 0;
    /* sdd-asis-lifecycle:end */
};

/**
 * @event
 * @name scwin.btn_Excel_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Excel_onclick = async function () {
    try {
        /* sdd-asis-lifecycle:begin btn_Excel_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.excelDown();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf05005.btn_Excel_onclick' }); }
};

/**
 * @event
 * @name scwin.grd_List_ondblclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param row colid
 * @returns
 * @hidden N
*/
scwin.grd_List_ondblclick = function (row, colid) {
    try {
        /* sdd-asis-lifecycle:begin grd_List_ondblclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.openDetail(row);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf05005.grd_List_ondblclick' }); }
};

/**
 * @event
 * @name scwin.btn_New_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_New_onclick = async function () {
    try {
        /* sdd-asis-lifecycle:begin btn_New_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if ($c.fil.getObjectValue(slc_cmb_NEW_SECUGRP_ID) === "") {
            await $c.win.alert("신규등록할 [유가증권]을 선택하세요.");
            $c.util.getComponent("slc_cmb_NEW_SECUGRP_ID").focus();
            return;
        } else {
            scwin.openDetail(-999);
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf05005.btn_New_onclick' }); }
};

/**
 * @event
 * @name scwin.img_CoSearch_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.img_CoSearch_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin img_CoSearch_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.lc.fn_PopFindExamCorp($c.fil.getObjectValue(rd_rdo_SECUGRP_ID));
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf05005.img_CoSearch_onclick' }); }
};

/**
 * @event
 * @name scwin.txb_ISUR_CD_onblur
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.txb_ISUR_CD_onblur = function () {
    try {
        /* sdd-asis-lifecycle:begin txb_ISUR_CD_onblur — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if (ipt_txb_ISUR_CD.value === "") {
            $c.util.getComponent("ipt_txb_COM_NM").setValue("");
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf05005.txb_ISUR_CD_onblur' }); }
};

/**
 * @event
 * @name scwin.cmb_PeriodTp_onselchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.cmb_PeriodTp_onselchange = function () {
    try {
        /* sdd-asis-lifecycle:begin cmb_PeriodTp_onselchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        const vTp = slc_cmb_PeriodTp.valueOfIndex("VALUE", slc_cmb_PeriodTp.Index);
        $c.fil.fn_setFromToDate(vTp, cal_edt_SDate, cal_edt_EDate);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf05005.cmb_PeriodTp_onselchange' }); }
};

/**
 * @event
 * @name scwin.btn_Close_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Close_onclick = function () {
    try {
        /* sdd-asis-lifecycle:begin btn_Close_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.frame.CloseFrame();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf05005.btn_Close_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_script_dts_List
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_script_dts_List = async function () {
    $c.util.getComponent("dma_scriptDts_ListReq").set("SCREN_ID", "ULDSTF05005.gfm");
    $c.util.getComponent("dma_scriptDts_ListReq").set("inputMessageId", "NEWLISTING_SEARCH_OUT");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD, DIV_IDX, SECUGRP_ID, ISUR_CD, S_DATE, E_DATE, SPOT_ISU_TRD_MKT_TP_CD", unresolved: "query_param:SCREN_PROCES_TP_CD,DIV_IDX,SECUGRP_ID,ISUR_CD,S_DATE,E_DATE,SPOT_ISU_TRD_MKT_TP_CD" };
    const sbmOptions = {
        id: "tx_script_dts_List",
        method: "post",
        action: "/Newlisting.do",
        ref: "dma_scriptDts_ListReq",
        target: "dts_List=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_List_onloaderror'] === 'function') ? scwin['dts_List_onloaderror'] : (typeof scwin['dts_List_onfail'] === 'function') ? scwin['dts_List_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_List_onloadcompleted'] === 'function') ? scwin['dts_List_onloadcompleted'] : ((typeof scwin['dts_List_onsuccess'] === 'function') ? scwin['dts_List_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_List'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf05005.tx_script_dts_List" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 09. 29
 * @param arrPar
 * @returns
 * @hidden N
*/
scwin.getPar = function (arrPar) {
    /* sdd-asis-lifecycle:begin fn_GetPar — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    arrPar[0] = $c.fil.getObjectValue(ipt_txb_ISUR_CD);
    arrPar[1] = $c.fil.getObjectValue(ipt_txb_COM_NM);
    arrPar[2] = $c.fil.getObjectValue(rd_rdo_SECUGRP_ID);
    arrPar[3] = $c.fil.getObjectValue(rd_rdo_SPOT_ISU_TRD_MKT_TP_CD);
    arrPar[4] = SEARCH_TYP_SLR;
    return arrPar , length;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setPar
 * @author Inswave
 * @date 2026. 09. 29
 * @param arrPar
 * @returns
 * @hidden N
*/
scwin.setPar = function (arrPar) {
    /* sdd-asis-lifecycle:begin fn_SetPar — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("ipt_txb_ISUR_CD").setValue(arrPar[0].ISUR_CD);
    $c.util.getComponent("ipt_txb_COM_NM").setValue(arrPar[0].COM_NM);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setBzProcsNo
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.setBzProcsNo = function (obj) {
    /* sdd-asis-lifecycle:begin fn_setBzProcsNo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.clickBzProcsNo = scwin.dts_List.getCellData((obj), "BZ_PROCS_NO");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getBzProcsNo
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getBzProcsNo = function () {
    /* sdd-asis-lifecycle:begin fn_getBzProcsNo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    return scwin.clickBzProcsNo;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.excelDown
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.excelDown = async function () {
    /* sdd-asis-lifecycle:begin fn_ExcelDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (scwin.dts_List.getRowCount() > 0) {
        $c.fil.doLogSave(scwin.vScrenID, $c.fil.SCREN_PROCS_TP_CD_07);
        scwin.grd_List.GridToOffice("신규상장", "", 8, 0);
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.openDetail
 * @author Inswave
 * @date 2026. 09. 29
 * @param row
 * @returns
 * @hidden N
*/
scwin.openDetail = function (row) {
    /* sdd-asis-lifecycle:begin fn_OpenDetail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let hight;
    let secugrpId;
    let pageNM;
    if (row > 0) {
        scwin.setBzProcsNo(row);
        secugrpId = scwin.dts_List.getCellData(row, 'SECUGRP_ID');
    } else {
        scwin.clickBzProcsNo = "";
        secugrpId = $c.fil.getObjectValue(slc_cmb_NEW_SECUGRP_ID);
    }
    if (secugrpId === SECUGRP_ID_ST) {
        hight = "900";
        pageNM = "ULDSTF05006";
    } else {
        if (secugrpId === SECUGRP_ID_DR || secugrpId === SECUGRP_ID_FS) {
            hight = "900";
            pageNM = "ULDSTF05007";
        }
    }
    $c.frame.CreateDialogFrame("STOCK_LISTING", (function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })("/lstproc/" + pageNM + ".gfm"), $c.lc.fn_getSecuGrpNm(secugrpId) + " 신규상장관리", 220, 0, 1020, hight, "window");
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
scwin.fn_list_sync = scwin.tx_script_dts_List;
